package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class MigrationMappingsBrowserAcceptance {
 static void click(Page p,String name){ServiceOutagesBrowserAcceptance.click(p,name);}
 static void run(BrowserTest h)throws Exception{
  MigrationMappingsAcceptance.seed();String sourceId=id();MigrationSource.tables.put("incident",List.of(map("sys_id",sourceId,"short_description","Browser mapped incident","state","1","priority","3","custom_details","Browser renamed field survived")));var fields=new ArrayList<>(MigrationSource.tables.get("sys_dictionary"));fields.getFirst().put("column_label","Untrusted <script>metadata</script>");MigrationSource.tables.put("sys_dictionary",fields);
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/migrations");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess source fields and prepare a reviewed mapping")).press("Enter");page.getByLabel("Source origin").fill(MigrationSource.origin());page.getByLabel("Source table",new Page.GetByLabelOptions().setExact(true)).fill("incident");page.getByLabel("Destination table").selectOption("incident");page.getByLabel("Source OAuth bearer token").fill(MigrationSource.TOKEN);click(page,"Assess visible metadata");String assessmentUrl=page.url();assertThat(page.locator("main")).containsText("Untrusted <script>metadata</script>");assertThat(page.locator("main script")).hasCount(0);assertFalse(page.content().contains(MigrationSource.TOKEN));assertThat(page.locator("main")).containsText("incident → task");page.getByLabel("Field mapping and value translations").fill(JSON.writeValueAsString(MigrationMappingsAcceptance.mapping()));click(page,"Review exact migration plan");assertThat(page.locator("pre")).containsText("custom_details");assertThat(page.locator("pre")).containsText("\"history\" : false");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/migration-mapping-reviewed-light.png")).setFullPage(true));click(page,"Dark mode");page.setViewportSize(390,844);page.getByRole(AriaRole.REGION,new Page.GetByRoleOptions().setName("Visible source field metadata")).focus();assertThat(page.getByRole(AriaRole.REGION,new Page.GetByRoleOptions().setName("Visible source field metadata"))).isFocused();ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/migration-mapping-reviewed-dark.png")).setFullPage(true));page.getByLabel("Create this exact migration plan").check();click(page,"Create reviewed migration");assertThat(page.locator("main")).containsText("Migration created");String assessment=assessmentUrl.substring(assessmentUrl.lastIndexOf('/')+1),job;try(var db=h.store.open()){PlatformFoundationTest.bind(db);job=MigrationMappings.page(db,assessment).get("job_id").toString();}page.reload();assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create reviewed migration"))).hasCount(0);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Fetch this migration")).press("Enter");assertThat(page.locator("main")).containsText("background worker is disabled");page.navigate(h.base()+"/admin/migrations");TransferBrowserAcceptance.saved(page);page.locator("#migration-jobs").selectOption(job);page.locator("#migration-token").fill(MigrationSource.TOKEN);page.locator("#migration-fetch").click();assertThat(page.locator("#migration-report")).containsText("review");TransferBrowserAcceptance.saved(page);page.locator("#migration-preview").click();TransferBrowserAcceptance.saved(page);page.locator("#migration-apply").click();assertThat(page.locator("#migration-report")).containsText("\"preview\": false");page.navigate(h.base()+"/record/incident/"+sourceId);assertThat(page.locator("main")).containsText("Browser mapped incident");assertThat(page.locator("textarea[name=description]")).hasValue("Browser renamed field survived");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/migration-mapping-result-dark.png")).setFullPage(true));assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));
  }finally{MigrationSource.reset();}
 }
}
